    def parse_ws_trade(self, trade: object, market: Market = None):
        #
        #   [
        #         1894994106,  # id
        #         1656151427.729706,  # deal time
        #         "LTC_USDT",  # symbol
        #         96624037337,  # order id
        #         "56.78",  # price
        #         "0.16717",  # amount
        #         "0.0094919126",  # fee
        #         '',  # client order id
        #         "2",  # side, 1 = sell, 2 = buy
        #         "2",  # role, 1 = maker, 2 = taker
        #         "LTC"  # fee asset
        #    ]
        #
        orderId = self.safe_string(trade, 3)
        timestamp = self.safe_timestamp(trade, 1)
        id = self.safe_string(trade, 0)
        price = self.safe_string(trade, 4)
        amount = self.safe_string(trade, 5)
        marketId = self.safe_string(trade, 2)
        market = self.safe_market(marketId, market)
        fee = None
        feeCost = self.safe_string(trade, 6)
        if feeCost is not None:
            feeCurrencyId = self.safe_string(trade, 10)
            feeCurrencyCode = self.safe_currency_code(feeCurrencyId) if (feeCurrencyId is not None) else market['quote']
            fee = {
                'cost': feeCost,
                'currency': feeCurrencyCode,
            }
        rawSide = self.safe_integer(trade, 8)
        side = None
        if rawSide == 1:
            side = 'sell'
        elif rawSide == 2:
            side = 'buy'
        role = self.safe_integer(trade, 9)
        takerOrMaker = None
        if role == 1:
            takerOrMaker = 'maker'
        elif role == 2:
            takerOrMaker = 'taker'
        return self.safe_trade({
            'id': id,
            'info': trade,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': market['symbol'],
            'order': orderId,
            'type': None,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': price,
            'amount': amount,
            'cost': None,
            'fee': fee,
        }, market)

